python3 - <<'EOF'
p='src/expenseReview.ts'
s=open(p).read()
start=s.index('const COLUMNS')
new='''const COLUMNS = ["date", "employee", "category", "amount", "currency", "receipt"] as const;
type Column = (typeof COLUMNS)[number];

interface Header {
  index: Record<Column, number>;
  width: number;
}

interface Expense {
  date: string;
  employee: string;
  category: string;
  /** The amount as written, in cents of its currency. */
  amountCents: number;
  currency: string;
  chfCents: number;
  receipt: boolean;
}

function readHeader(text: string): Header {
  const names = splitFields(text).map((name) => name.trim().toLowerCase());
  const index = {} as Record<Column, number>;
  for (const column of COLUMNS) {
    index[column] = names.indexOf(column);
    if (index[column] < 0) throw new ExpenseFileError(`Missing column: ${column}`);
  }
  return { index, width: names.length };
}

/** cents * rate rounded half up, computed on the decimal digits of the rate so binary floats cannot tip a half. */
function convertCents(cents: number, rate: number): number {
  const [mantissa, exponent = "0"] = String(rate).split("e");
  const [whole, fraction = ""] = mantissa.split(".");
  const scale = fraction.length - Number(exponent);
  const product = BigInt(cents) * BigInt(whole + fraction);
  if (scale <= 0) return Number(product * 10n ** BigInt(-scale));
  const divisor = 10n ** BigInt(scale);
  return Number((product * 2n + divisor) / (divisor * 2n));
}

/** The expense in a data row, or the reason the row is rejected. */
function readRow(text: string, header: Header, policy: Policy, fxRates: FxRates): Expense | string {
  const fields = splitFields(text);
  if (fields.length !== header.width) return "wrong number of fields";
  const get = (column: Column) => fields[header.index[column]].trim();
  const date = get("date");
  if (!isCalendarDate(date)) return "invalid date";
  const employee = get("employee");
  if (employee === "") return "missing employee";
  const category = get("category");
  if (!Object.hasOwn(policy.categories, category)) return "unknown category";
  const amount = /^(\\d+)(?:\\.(\\d{1,2}))?$/.exec(get("amount"));
  const amountCents = amount ? Number(amount[1]) * 100 + Number((amount[2] ?? "").padEnd(2, "0")) : 0;
  if (amountCents <= 0) return "invalid amount";
  const currency = get("currency");
  if (currency !== "CHF" && !Object.hasOwn(fxRates, currency)) return "unknown currency";
  const receipt = get("receipt").toLowerCase();
  if (receipt !== "yes" && receipt !== "no") return "invalid receipt flag";
  const chfCents = convertCents(amountCents, currency === "CHF" ? 1 : fxRates[currency]);
  return { date, employee, category, amountCents, currency, chfCents, receipt: receipt === "yes" };
}

export function reviewExpenses(csv: string, policy: Policy, fxRates: FxRates): ExpenseReport {
  const lines = csv.split(/\\r?\\n/);
  const headerIndex = lines.findIndex((text) => text.trim() !== "");
  if (headerIndex < 0) throw new ExpenseFileError("Missing header");
  const header = readHeader(lines[headerIndex]);
  const report: ExpenseReport = { lines: [], rejected: [], totals: {} };
  for (let i = headerIndex + 1; i < lines.length; i++) {
    if (lines[i].trim() === "") continue;
    const expense = readRow(lines[i], header, policy, fxRates);
    if (typeof expense === "string") {
      report.rejected.push({ line: i + 1, reason: expense });
      continue;
    }
    const { date, employee, category, chfCents } = expense;
    report.lines.push({ line: i + 1, date, employee, category, amountChfCents: chfCents, violations: [] });
    const total = (report.totals[employee] ??= { approvedCents: 0, flaggedCents: 0 });
    total.approvedCents += chfCents;
  }
  return report;
}
'''
